// Resolve a probe target per runtime_kind. Most runtimes have NO external
// service to probe — they run in-process (direct_llm = the model router) or via
// the DB rail (hermes = evaluate_story_self) or ARE the workflow engine itself
// (workflow = this n8n). Those are 'self-healthy': mark healthy without an HTTP
// call. Only runtimes backed by an external service are HTTP-probed:
//   * openclaw → $env.OPENCLAW_URL + $env.OPENCLAW_HEALTH_PATH (default /health)
//   * cli      → $env.AGENT_RUNNER_URL + /health (svc-agent-runner), if configured
// A runtime whose external service env is absent is recorded 'down' (the WF can't
// reach it, so the resolver must not pick it) — fail-loud at the registry layer.

const input = $input.first().json;
const kind = String(input.runtime_kind || '');

const selfHealthy = (detail) => [{ json: {
  slug: input.slug, runtime_kind: kind,
  skip_http: true, status: 'healthy', latency_ms: 0, detail,
  probe_url: '', auth_header_name: 'X-Probe', auth_header_value: 'self',
} }];

const httpProbe = (url, detail) => [{ json: {
  slug: input.slug, runtime_kind: kind,
  skip_http: false, probe_url: url, probe_started_at: Date.now(), detail,
  auth_header_name: 'X-Probe', auth_header_value: 'runtime',
} }];

const down = (detail) => [{ json: {
  slug: input.slug, runtime_kind: kind,
  skip_http: true, status: 'down', latency_ms: 0, detail,
  probe_url: '', auth_header_name: 'X-Probe', auth_header_value: 'self',
} }];

if (kind === 'direct_llm' || kind === 'hermes' || kind === 'workflow') {
  return selfHealthy(`${kind}: in-process / DB-rail / workflow engine — no external service`);
}
if (kind === 'openclaw') {
  const base = String(process.env.OPENCLAW_URL || '').replace(/\/+$/, '');
  if (!base) return down('openclaw: OPENCLAW_URL not configured');
  const path = process.env.OPENCLAW_HEALTH_PATH || '/health';
  return httpProbe(`${base}${path}`, 'openclaw health endpoint');
}
if (kind === 'cli') {
  const base = String(process.env.AGENT_RUNNER_URL || '').replace(/\/+$/, '');
  if (!base) return down('cli: AGENT_RUNNER_URL not configured');
  return httpProbe(`${base}/health`, 'svc-agent-runner health endpoint');
}
return down(`${kind}: no probe strategy`);

// Classify an HTTP runtime probe into adapter_health enum: healthy|degraded|down.
// For a RUNTIME the question is REACHABILITY — any HTTP response means the
// service is up (even 404 = no /health route but the server answered):
//   * any 2xx/3xx/4xx response → healthy (service reachable; latency>=3s → degraded)
//   * 5xx                      → degraded (up but erroring)
//   * network error / timeout  → down (service unreachable)

const orig = $('Resolve Probe Target').first().json;
const latencyMs = Date.now() - Number(orig.probe_started_at || Date.now());
const input = $input.first().json;
const httpStatus = Number(input.statusCode || input.status || 0);

let status = 'down';
let detail = '';
if (input.error) {
  status = 'down';
  detail = `unreachable: ${String(input.error).slice(0, 200)}`;
} else if (httpStatus >= 500) {
  status = 'degraded';
  detail = `HTTP ${httpStatus} (5xx — up but erroring) in ${latencyMs}ms`;
} else if (httpStatus >= 200 && httpStatus < 500) {
  status = latencyMs >= 3000 ? 'degraded' : 'healthy';
  detail = `HTTP ${httpStatus} (reachable) in ${latencyMs}ms`;
} else {
  status = 'down';
  detail = `no response (status ${httpStatus})`;
}

return [{ json: { slug: orig.slug, runtime_kind: orig.runtime_kind, status, latency_ms: latencyMs, detail } }];
